-- ============================================================================
-- Employee master seed for assetiq_db (source of the Workday FDW)
--
-- Populates:
--   workday_employees (76 employees)
--
-- Usage:
--   psql -U postgres -d assetiq_db -f db/seed_assetiq_employees.sql
--
-- The tokeniq_db backend reads these rows through the foreign table
-- assetiq_fdw.workday_employees (see db/README.md).
--
-- Safe to re-run: the TRUNCATE below clears the table first.
-- Regenerated from a live DB with:
--   pg_dump -a --inserts --rows-per-insert=50 --no-owner --no-privileges \
--     -t workday_employees assetiq_db
-- ============================================================================

TRUNCATE TABLE workday_employees RESTART IDENTITY CASCADE;

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

-- Data for Name: workday_employees; Type: TABLE DATA; Schema: public; Owner: -



-- Name: workday_employees_employee_id_seq; Type: SEQUENCE SET; Schema: public; Owner: -

SELECT pg_catalog.setval('public.workday_employees_employee_id_seq', 76, true);
